old_signal="""    signal(region,roll,choice,{excludeIds=[],runContext={}}={}){if(blocked||!Object.hasOwn(REGIONS,region)||![roll,choice].every(n=>Number.isFinite(n)&&n>=0&&n<1))return null;const gate=fieldInsightOpportunityEligibility(runContext),nitrogen=nitrogenCriticalInsightCandidate(state,{fieldContext:region===NITROGEN_REGION_ID,nitrogenEngaged:gate.ready,foundElements:runContext?.foundElements??[]});if(nitrogen)return {recipe:nitrogen,critical:true};if(region===NITROGEN_REGION_ID&&nitrogenChapterState(state).stage==='nitrogen-critical')return {deferred:true,critical:true};const p=state.progress,last=p.signalLast[region];if(last!==undefined&&p.totalCollected-last<45)return {repeat:true};const frontier=frontierSignal(region,runContext);if(frontier?.managed){if(frontier.recipe){p.signalMisses=0;p.signalLast[region]=p.totalCollected;save();return {recipe:frontier.recipe,frontier:true};}if(frontier.deferred)return {deferred:true,frontier:true};return signalBonus(region,p);}const excluded=excludeIds instanceof Set?excludeIds:new Set(Array.isArray(excludeIds)?excludeIds:[]),candidates=[...records.values()].filter(rec=>signalCandidateEligible(rec,{region,recipes:state.recipes,hints:state.hints,excludeIds:excluded,canUseElement:el=>MANAGED.includes(el)&&api.canUseElement(el)}));if(candidates.length&&(roll<GROWTH.signalChance||p.signalMisses+1>=GROWTH.signalPity)){const rec=candidates[Math.floor(choice*candidates.length)];p.signalMisses=0;p.signalLast[region]=p.totalCollected;save();return {recipe:rec.id};}if(candidates.length)p.signalMisses++;return signalBonus(region,p);},\n"""
new_signal="""    signal(region,roll,choice,{excludeIds=[],runContext={},claimableOnly=false}={}){if(blocked||!Object.hasOwn(REGIONS,region)||![roll,choice].every(n=>Number.isFinite(n)&&n>=0&&n<1))return null;if(claimableOnly&&!signalClaimability(region,roll,choice,{excludeIds,runContext}).claimable)return {deferred:true,claimable:false};const gate=fieldInsightOpportunityEligibility(runContext),nitrogen=nitrogenCriticalInsightCandidate(state,{fieldContext:region===NITROGEN_REGION_ID,nitrogenEngaged:gate.ready,collectedElements:runContext?.collectedElements??{}});if(nitrogen)return {recipe:nitrogen,critical:true};if(region===NITROGEN_REGION_ID&&nitrogenChapterState(state).stage==='nitrogen-critical')return {deferred:true,critical:true};const p=state.progress,last=p.signalLast[region];if(last!==undefined&&p.totalCollected-last<45)return {repeat:true};const frontier=frontierSignal(region,runContext);if(frontier?.managed){if(frontier.recipe){p.signalMisses=0;p.signalLast[region]=p.totalCollected;save();return {recipe:frontier.recipe,frontier:true};}if(frontier.deferred)return {deferred:true,frontier:true};return signalBonus(region,p);}const excluded=normalizedExcludeIds(excludeIds),candidates=fallbackSignalCandidates(region,excluded);if(candidates.length&&(roll<GROWTH.signalChance||p.signalMisses+1>=GROWTH.signalPity)){const rec=candidates[Math.floor(choice*candidates.length)];p.signalMisses=0;p.signalLast[region]=p.totalCollected;save();return {recipe:rec.id};}if(candidates.length)p.signalMisses++;return signalBonus(region,p);},\n"""
patch('src/veil/resources.js',old_signal,new_signal)

# N2 eligibility must use this expedition's actual cargo, never persistent discovery.
patch('src/veil/nitrogen-progression.js',
"export function nitrogenCriticalInsightCandidate(state,{regionAvailable=NITROGEN_REGION_AVAILABLE,fieldContext=false,nitrogenEngaged=false,foundElements=[]}={}){\n  const chapter=nitrogenChapterState(state,{regionAvailable});\n  if(!chapter.eligible||!chapter.destinationAvailable||chapter.nitrogenKnown||fieldContext!==true||nitrogenEngaged!==true)return null;\n  const found=new Set([...(Array.isArray(state?.progress?.foundElements)?state.progress.foundElements:[]),...(Array.isArray(foundElements)?foundElements:[])]);\n  return found.has('N')?NITROGEN_MOLECULE_ID:null;\n}\n",
"export function nitrogenCriticalInsightCandidate(state,{regionAvailable=NITROGEN_REGION_AVAILABLE,fieldContext=false,nitrogenEngaged=false,collectedElements={}}={}){\n  const chapter=nitrogenChapterState(state,{regionAvailable});\n  if(!chapter.eligible||!chapter.destinationAvailable||chapter.nitrogenKnown||fieldContext!==true||nitrogenEngaged!==true)return null;\n  return Number(collectedElements?.N)>0?NITROGEN_MOLECULE_ID:null;\n}\n")

